  1	//! `libio/genops.c`: the generic stream operations, home of `FILE` (`struct _IO_FILE`).
  2	//!
  3	//! [`File`] is C's stream, bound opaque and borrowed: the routines that open, write and
  4	//! close a stream are C's, and Rust holds a stream only through the [`FileRef`] that
  5	//! whatever keeps it open lends.
  6	
  7	pub use ffi_import::{File, FileMut, FileRef};
  8	
  9	#[expect(unsafe_code, reason = "asserts the thread safety of glibc's streams")]
 10	mod ffi_import {
 11	    use ffibox::define_ctype;
 12	
 13	    use crate::libc::ffi;
 14	
 15	    define_ctype!(
 16	        /// Wraps `st::_IO_FILE`
 17	        ///
 18	        /// Wraps `tdf::FILE`
 19	        ///
 20	        /// C's stream, `FILE`: a file, a buffer or a cookie behind glibc's stdio buffer,
 21	        /// which C's stdio routines read, write and close. Opaque: the safe API reads and
 22	        /// writes none of its fields.
 23	        ///
 24	        /// Borrowed only. C allocates every stream (`fopen`, `fdopen`, `tmpfile`,
 25	        /// `open_memstream` and their kin, or the static storage of `stdin`, `stdout` and
 26	        /// `stderr`) and releases it with `fclose`, and glibc keeps the address of every
 27	        /// file-backed stream in its list of open streams, which `exit` flushes, from its
 28	        /// opening to its close. So no `File` value exists in Rust, and no owner: a stream
 29	        /// is reached through a [`FileRef`] borrowed from what keeps it open, the C caller
 30	        /// that hands it for a call, or the program, for the standard streams.
 31	        ///
 32	        /// Shared. C writes a stream's buffer and state from every stdio call, under the
 33	        /// stream's lock: a recursive lock of its own, which each stdio routine takes,
 34	        /// unless the stream's locking is the caller's (`__fsetlocking` with
 35	        /// `FSETLOCKING_BYCALLER`) or the routine is an `_unlocked` one, and which
 36	        /// `flockfile` takes whatever the stream's locking. [`FileRef`] is `Send` and
 37	        /// `Sync` on that lock: every operation bound on it holds the lock, taken with
 38	        /// `flockfile`, for the whole of its access to the stream, and reads nothing of
 39	        /// the stream without it. No producer yields a [`FileMut`]: nothing holds a stream
 40	        /// exclusively.
 41	        ///
 42	        /// A stream C hands Rust is borrowed with `FileRef::from_ptr`, whose contract
 43	        /// reads, for a stream: the pointer is NULL or an open stream that stays open for
 44	        /// the handle's lifetime, `fclose` included, and every other access to it while
 45	        /// the handle lives, C's or Rust's, on any thread, holds its lock. glibc's stdio
 46	        /// routines take that lock themselves only while the stream's locking is internal,
 47	        /// its default. On a stream set to `FSETLOCKING_BYCALLER`, every routine skips it,
 48	        /// `fflush(NULL)` and `exit`'s flush of every open stream included, and the
 49	        /// `_unlocked` routines skip it on every stream: the C that uses them holds the
 50	        /// lock itself, with `flockfile`, or the stream is not borrowed while it runs.
 51	        #[doc(alias = "_IO_FILE")]
 52	        #[doc(alias = "FILE")]
 53	        File,
 54	        FileRef,
 55	        FileMut,
 56	        ffi::_IO_FILE
 57	    );
 58	
 59	    // SAFETY: a stream is tied to no thread: glibc opens, writes and closes it from any
 60	    // thread, its lock recording an owner only while a call holds it. No `File` value
 61	    // exists in Rust (the field is private and this region builds none), so a `File`
 62	    // crosses threads only behind a pointer: an ffibox owner or view over it, which
 63	    // inherits this assertion, and which a later region may add, its stream then closed
 64	    // or reached on whichever thread holds it; the handles assert their own below.
 65	    unsafe impl Send for File {}
 66	    // SAFETY: as for `Send for File`: the exclusive handle holds no lock and no state of
 67	    // its own, only the pointer.
 68	    unsafe impl Send for FileMut<'_> {}
 69	    // SAFETY: nothing reachable through a shared handle touches the stream but under the
 70	    // stream's lock: `FileRef` reads no field, and every operation a region adds on it
 71	    // holds the lock, taken with `flockfile`, which locks whatever the stream's locking
 72	    // mode, for the whole of its access, so that two threads' operations exclude each
 73	    // other, and every other access, which `FileRef::from_ptr`'s contract for a stream
 74	    // makes hold the lock too.
 75	    unsafe impl Sync for File {}
 76	    // SAFETY: as for `Sync for File`: copies of a shared handle reach the stream only
 77	    // through its locked operations.
 78	    unsafe impl Send for FileRef<'_> {}
 79	    // SAFETY: as above.
 80	    unsafe impl Sync for FileRef<'_> {}
 81	    // SAFETY: `&FileMut` reaches the stream only through `as_ref`, a shared handle.
 82	    unsafe impl Sync for FileMut<'_> {}
 83	
 84	    #[cfg(test)]
 85	    #[expect(unsafe_code, reason = "borrows stand-in streams through the seams")]
 86	    mod unit_priv {
 87	        use core::ptr;
 88	        use std::thread;
 89	
 90	        use ffibox::{CMutSeam, CRefSeam};
 91	
 92	        use super::{File, FileMut, FileRef};
 93	        use crate::libc::ffi;
 94	
 95	        /// The fixture of these tests, which hand the stream to no C routine and read
 96	        /// nothing of it: zeroed storage of a stream's layout, which stands in for an open
 97	        /// stream as far as a handle, which carries only its pointer, can tell.
 98	        fn storage() -> ffi::_IO_FILE {
 99	            ffi::_IO_FILE::default()
100	        }
101	
102	        fn send_sync<T: Send + Sync>() {}
103	
104	        #[test]
105	        fn a_null_stream_is_no_handle() {
106	            // SAFETY: NULL is the input `from_ptr` reads as no handle.
107	            assert!(unsafe { FileRef::from_ptr(ptr::null_mut()) }.is_none());
108	            // SAFETY: as above.
109	            assert!(unsafe { FileMut::from_ptr(ptr::null_mut()) }.is_none());
110	        }
111	
112	        #[test]
113	        fn the_handles_keep_the_stream_address() {
114	            let mut stream = storage();
115	            let p = &raw mut stream;
116	            // SAFETY: `stream` is live and initialised for the handle's lifetime, and
117	            // nothing else writes it.
118	            let shared = unsafe { FileRef::from_ptr(p) }.unwrap();
119	            assert_eq!(shared.as_ptr(), p.cast_const());
120	            let copy = shared;
121	            assert_eq!(copy.as_ptr(), shared.as_ptr());
122	
123	            // SAFETY: as above, from a pointer with write provenance; `shared` and `copy`
124	            // are not used while the exclusive handle lives.
125	            let mut exclusive = unsafe { FileMut::from_ptr(p) }.unwrap();
126	            assert_eq!(exclusive.as_mut_ptr(), p);
127	            assert_eq!(exclusive.as_ref().as_ptr(), p.cast_const());
128	            let mut reborrow = exclusive.as_mut();
129	            assert_eq!(reborrow.as_mut_ptr(), p);
130	            assert_eq!(exclusive.as_mut_ptr(), p);
131	        }
132	
133	        #[test]
134	        fn a_shared_handle_crosses_threads() {
135	            send_sync::<File>();
136	            send_sync::<FileRef<'static>>();
137	            send_sync::<FileMut<'static>>();
138	
139	            let mut stream = storage();
140	            let p = &raw mut stream;
141	            // SAFETY: `stream` outlives the scope every thread runs in, and nothing writes
142	            // it.
143	            let shared = unsafe { FileRef::from_ptr(p) }.unwrap();
144	            let addr = p.addr();
145	            thread::scope(|s| {
146	                for _ in 0..8 {
147	                    s.spawn(move || assert_eq!(shared.as_ptr().addr(), addr));
148	                }
149	            });
150	
151	            // SAFETY: as above, from a pointer with write provenance, and no other handle is
152	            // used while it lives.
153	            let exclusive = unsafe { FileMut::from_ptr(p) }.unwrap();
154	            let moved =
155	                thread::scope(|s| s.spawn(move || exclusive.as_ref().as_ptr().addr()).join());
156	            assert_eq!(moved.unwrap(), addr);
157	        }
158	    }
159	}

