     1	//! `libio/stdio.c`: the standard streams `stdin`, `stdout` and `stderr`.
     2	//!
     3	//! [`stderr`] is C's standard error stream, lent for the whole program as a
     4	//! [`FileRef<'static>`](crate::libc::libio::genops::FileRef). `stdin` and `stdout` are not
     5	//! bound yet.
     6	
     7	pub use ffi_import::stderr;
     8	
     9	#[expect(
    10	    unsafe_code,
    11	    reason = "reads glibc's `stderr` and borrows the stream it names"
    12	)]
    13	mod ffi_import {
    14	    use ffibox::CRefSeam;
    15	
    16	    use crate::libc::ffi;
    17	    use crate::libc::libio::genops::FileRef;
    18	
    19	    /// Wraps `glb::stderr`
    20	    ///
    21	    /// The standard error stream: the stream C's `stderr` names when the call reads it, as
    22	    /// C's `stderr` expression does, lent for the rest of the program.
    23	    ///
    24	    /// glibc defines `stderr` with its stream's address, `_IO_2_1_stderr_`, a stream in
    25	    /// static storage, unbuffered and open on descriptor 2, which is never freed: even
    26	    /// `fclose` keeps the storage of a standard stream. No glibc routine assigns `stderr`
    27	    /// (only its tests and its programs do, and a compatibility constructor for binaries
    28	    /// linked against glibc 2.0, which runs before `main`), so every call returns that
    29	    /// stream. It is shared: every C stdio routine and every operation bound on
    30	    /// [`FileRef`] holds its lock, as [`FileRef`]'s contract for a borrowed stream says.
    31	    ///
    32	    /// The `'static` borrow assumes what that contract asks of a stream for the whole
    33	    /// program, which neither the C of `crustify-rs/libgit2-bindings` nor that of
    34	    /// `crustify-rs/ffmpeg-bindings` breaks:
    35	    ///
    36	    /// - no code assigns `stderr` while another thread may read it, and whatever stream it names
    37	    ///   stays open until the program ends: nothing passes it to `fclose`, or to a `freopen` that
    38	    ///   fails and leaves it closed. A `freopen` that succeeds keeps the stream open at its
    39	    ///   address, under its lock throughout;
    40	    /// - its locking stays internal, glibc's default: nothing sets it to `FSETLOCKING_BYCALLER`
    41	    ///   with `__fsetlocking`, and an `_unlocked` routine reaches it only under `flockfile`, as
    42	    ///   glibc's own `error` does.
    43	    ///
    44	    /// A handle taken before C assigns `stderr` keeps the stream it was taken from.
    45	    ///
    46	    /// # Panics
    47	    ///
    48	    /// If C has set `stderr` to NULL, which no C of glibc or of either parent does.
    49	    #[must_use]
    50	    pub fn stderr() -> FileRef<'static> {
    51	        // SAFETY: `stderr` is a pointer-sized global glibc initialises statically, before
    52	        // any Rust code runs, and no write races with this read of it: glibc never writes
    53	        // it, and the assumptions above exclude any other write while another thread may
    54	        // read it.
    55	        let stream = unsafe { ffi::stderr };
    56	        // SAFETY: `stream` is NULL, which `from_ptr` refuses, or an open stream, glibc's
    57	        // `_IO_2_1_stderr_` unless C assigned another, which stays open until the program
    58	        // ends and whose every access holds its lock, as the assumptions above state: the
    59	        // contract of `FileRef::from_ptr` for a stream, for the `'static` lifetime.
    60	        unsafe { FileRef::from_ptr(stream) }.expect("glibc's `stderr` is never NULL")
    61	    }
    62	}
    63	//! `stderr` against C's `stderr`: the handle is the stream C's expression reads.
    64	
    65	use std::thread;
    66	
    67	use ffibox::CRefSeam;
    68	use glibc_bindings::libc::ffi;
    69	use glibc_bindings::libc::libio::stdio::stderr;
    70	
    71	/// C's `stderr` expression: a read of the global.
    72	fn c_stderr() -> *const ffi::FILE {
    73	    // SAFETY: `stderr` is initialised before any Rust code runs, and no test writes it, so
    74	    // the read races with no write.
    75	    unsafe { ffi::stderr }.cast_const()
    76	}
    77	
    78	#[test]
    79	#[cfg_attr(miri, ignore = "reads a C global")]
    80	fn stderr_is_the_stream_c_names() {
    81	    for _ in 0..3 {
    82	        let c = c_stderr();
    83	        assert!(!c.is_null());
    84	        assert_eq!(stderr().as_ptr(), c);
    85	        assert_eq!(c_stderr(), c);
    86	    }
    87	    let there = thread::spawn(|| (stderr().as_ptr().addr(), c_stderr().addr()))
    88	        .join()
    89	        .unwrap();
    90	    assert_eq!(there.0, there.1);
    91	    assert_eq!(there.0, c_stderr().addr());
    92	}
    93	//! `stderr` through the safe API: a `'static` shared handle, kept past every scope and used
    94	//! from many threads at once.
    95	
    96	use std::sync::OnceLock;
    97	use std::thread;
    98	
    99	use ffibox::CRefSeam;
   100	use glibc_bindings::libc::libio::genops::FileRef;
   101	use glibc_bindings::libc::libio::stdio::stderr;
   102	
   103	/// A handle kept in a `static`, which outlives every scope that took it.
   104	static KEPT: OnceLock<FileRef<'static>> = OnceLock::new();
   105	
   106	#[test]
   107	#[cfg_attr(miri, ignore = "reads a C global")]
   108	fn the_handle_outlives_every_scope() {
   109	    let kept = *KEPT.get_or_init(stderr);
   110	    let detached = thread::spawn(move || kept.as_ptr().addr());
   111	    assert_eq!(detached.join().unwrap(), stderr().as_ptr().addr());
   112	    assert_eq!(KEPT.get().unwrap().as_ptr(), stderr().as_ptr());
   113	}
   114	
   115	#[test]
   116	#[cfg_attr(miri, ignore = "reads a C global")]
   117	fn threads_take_and_share_it_at_once() {
   118	    let mine = stderr();
   119	    let addrs: Vec<_> = thread::scope(|s| {
   120	        let threads: Vec<_> = (0..16)
   121	            .map(|_| {
   122	                s.spawn(move || {
   123	                    let mut taken = stderr().as_ptr().addr();
   124	                    for _ in 0..1000 {
   125	                        let again = stderr().as_ptr().addr();
   126	                        assert_eq!(again, taken);
   127	                        assert_eq!(mine.as_ptr().addr(), taken);
   128	                        taken = again;
   129	                    }
   130	                    taken
   131	                })
   132	            })
   133	            .collect();
   134	        threads.into_iter().map(|t| t.join().unwrap()).collect()
   135	    });
   136	    assert!(addrs.iter().all(|&a| a == mine.as_ptr().addr()));
   137	}
   138	//! `stderr`: one stream, the same on every call and every thread.
   139	
   140	use std::thread;
   141	
   142	use ffibox::CRefSeam;
   143	use glibc_bindings::libc::libio::stdio::stderr;
   144	
   145	#[test]
   146	#[cfg_attr(miri, ignore = "reads a C global")]
   147	fn every_call_lends_the_same_stream() {
   148	    let first = stderr();
   149	    assert!(!first.as_ptr().is_null());
   150	    for _ in 0..3 {
   151	        assert_eq!(stderr().as_ptr(), first.as_ptr());
   152	    }
   153	}
   154	
   155	#[test]
   156	#[cfg_attr(miri, ignore = "reads a C global")]
   157	fn every_thread_is_lent_the_same_stream() {
   158	    let here = stderr().as_ptr().addr();
   159	    let there = thread::spawn(|| stderr().as_ptr().addr()).join().unwrap();
   160	    assert_eq!(there, here);
   161	}
//! `libio/`: glibc's stdio streams.

pub mod genops;
pub mod stdio;

